public int IslandPerimeter(int[][] grid) {
    int land = 0, adj = 0;
    for (int y = 0; y < grid.Length; y++)
        for (int x = 0; x < grid[y].Length; x++) {
            if (grid[y][x] == 0) continue;
            land++;
            if (x + 1 < grid[y].Length && grid[y][x + 1] == 1) adj++; // neighbor to the right
            if (y + 1 < grid.Length && grid[y + 1][x] == 1) adj++;    // neighbor below
        }
    return 4 * land - 2 * adj;
}

